const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(data[0], 10);
const xs = [];
for (let i = 0; i < n; i++) {
  xs.push(parseInt(data[1 + i], 10));
}

const h = Math.max.apply(null, xs);
const lines = [];

for (let level = h; level >= 1; level--) {
  const row = new Array(n);
  for (let i = 0; i < n; i++) {
    row[i] = xs[i] >= level ? '1' : '0';
  }
  lines.push(row.join(' '));
}

process.stdout.write(lines.join('\n') + '\n');
